(() => {
 const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];
 const stages=[
 ['Configure the isolated testbed','Choose a line or star topology, record the seed and experiment settings, and connect Mininet hosts and Open vSwitch switches to Ryu through OpenFlow 1.3.','A documented experimental configuration and a connected SDN control/data plane.'],
 ['Generate a controlled workload','Run benign communication or a bounded synthetic security-relevant workload. The framework describes B00, B01, A01, A02, A03, and A04. Preserve execution start/end evidence rather than assuming that generated traffic proves attack success.','Recorded workload intervals and scenario execution evidence.'],
 ['Apply and verify the operational phases','Move through stable, constrained, and recovery settings. Traffic control applies the requested conditions; configuration checks and timestamped events establish which phase was actually present.','Verified phase boundaries and measured network response.'],
 ['Collect aligned telemetry','Combine OpenFlow flow statistics and packet/byte counters with RTT samples, UDP measurements, and experiment event timestamps. Preserve run identity and mark missing observations.','Observation windows with features and a traceable source experiment.'],
 ['Label, check, and partition','Assign phase, activity, and observation-quality context. Mark transition/mixed windows explicitly, validate evidence, and keep complete run IDs inside a single dataset partition.','The H14 export: 216 observations, 20 columns, three 72-row run-disjoint splits.'],
 ['Evaluate without mixing campaigns','Use separate campaigns for separate questions: H23 prospectively compares five frozen models on synthetic probing, while H28 measures phase-specific RTT and TCP bulk goodput.','Scoped model metrics and network-fidelity findings—not independent real-world attack validation.']
 ];
 const modelInfo=[
 {name:'Logistic Regression',principle:'A LINEAR SCORE → A PROBABILITY',how:'Weights combine the input features into a linear score. A sigmoid maps that score to a value between zero and one. A decision threshold turns the score into a class label.',role:'Acts as a linear classification baseline for the synthetic-probing target. Its simplicity provides a useful contrast with tree-based and nonlinear candidates.',note:'The animation uses one artificial input, a toy score, and a 0.5 threshold. These are not the paper’s learned coefficients or predictions.',ba:'62.50%',recall:'58.33%',fpr:'33.33%'},
 {name:'Random Forest',principle:'MANY TREES → AN AGGREGATED DECISION',how:'Multiple decision trees examine feature-based splits. Each tree contributes a class estimate; classification can aggregate votes or class probabilities across the forest.',role:'Provides a tree-ensemble candidate that can capture nonlinear feature interactions. In H23 it had the highest reported recall among the five candidates.',note:'Three toy trees explain aggregation. The study’s actual tree counts, thresholds, and learned paths are not reconstructed here.',ba:'88.75%',recall:'87.50%',fpr:'10.00%'},
 {name:'RBF-SVM',principle:'KERNEL SIMILARITY → A NONLINEAR BOUNDARY',how:'A support vector machine separates classes using a margin. The radial basis function kernel measures similarity between observations, allowing nonlinear decision boundaries in the original feature space.',role:'Supplies a nonlinear margin-based candidate. In the reported H23 evaluation it had zero recall and zero false positive rate, producing a balanced accuracy of 0.50.',note:'The two-dimensional boundary and moving point are illustrative. They are not fitted H14/H23 observations, support vectors, or the study’s learned boundary.',ba:'50.00%',recall:'0.00%',fpr:'0.00%'},
 {name:'Gradient Boosting',principle:'SEQUENTIAL TREES → PROGRESSIVE CORRECTIONS',how:'Weak learners are added sequentially. Each new learner improves the current ensemble by addressing errors or loss gradients, rather than training every learner independently.',role:'Provides a sequential tree-ensemble candidate. It achieved the highest reported H23 balanced accuracy at 0.8958; this does not establish a statistically significant advantage.',note:'The base score and three corrections are invented teaching values. They do not replay the study’s trained trees or residuals.',ba:'89.58%',recall:'79.17%',fpr:'0.00%'},
 {name:'Soft Voting Ensemble',principle:'CANDIDATE PROBABILITIES → A COMBINED ESTIMATE',how:'Soft voting combines class probabilities from participating classifiers, using equal or specified weights, then selects the class with the largest combined probability.',role:'Compares a combined classification approach with the individual candidates in the frozen H23 prospective evaluation.',note:'Four toy probability estimates are averaged with equal weights in this demo only. The actual training parameters and ensemble weights are not reconstructed.',ba:'87.50%',recall:'75.00%',fpr:'0.00%'}
 ];
 let step=0,model=0,signal=50,walk=false,modelPaused=false,last=0,time=0,modelTime=0,walkTime=0;
 function setStep(i){step=i;walkTime=0;qa('[data-workflow]').forEach(b=>{const active=Number(b.dataset.workflow)===i;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active);});q('#workflow-number').textContent=`STEP ${String(i+1).padStart(2,'0')} / 06`;q('#workflow-title').textContent=stages[i][0];q('#workflow-text').textContent=stages[i][1];q('#workflow-output').textContent=stages[i][2];q('#workflow-prev').disabled=i===0;q('#workflow-next').disabled=i===5;q('#workflow-canvas').setAttribute('aria-label',`Step ${i+1}: ${stages[i][0]}. ${stages[i][1]}`);q('#workflow-status').textContent=walk?`Playing step ${i+1} of 6`:`Step ${i+1} of 6 · ${stages[i][0]}`;}
 function stopWalk(){walk=false;q('#workflow-play').textContent='▶ Play the complete workflow';q('#workflow-play').setAttribute('aria-pressed','false');}
 qa('[data-workflow]').forEach(b=>b.addEventListener('click',()=>{stopWalk();setStep(Number(b.dataset.workflow));}));
 q('#workflow-prev').addEventListener('click',()=>{stopWalk();setStep(Math.max(0,step-1));});q('#workflow-next').addEventListener('click',()=>{stopWalk();setStep(Math.min(5,step+1));});
 q('#workflow-play').addEventListener('click',()=>{if(walk){stopWalk();setStep(step);return;}if(paused)setMotion(false);walk=true;q('#workflow-play').textContent='Ⅱ Pause walkthrough';q('#workflow-play').setAttribute('aria-pressed','true');setStep(step===5?0:step);});
 function setModel(i){model=i;const d=modelInfo[i];qa('[data-explain-model]').forEach(b=>{const active=Number(b.dataset.explainModel)===i;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active);});for(const [id,key] of [['model-principle','principle'],['model-name','name'],['model-how','how'],['model-role','role'],['model-demo-note','note'],['model-ba','ba'],['model-recall','recall'],['model-fpr','fpr']])q('#'+id).textContent=d[key];q('#model-canvas').setAttribute('aria-label',`Illustrative ${d.name} mechanics. ${d.how}`);}
 qa('[data-explain-model]').forEach(b=>b.addEventListener('click',()=>setModel(Number(b.dataset.explainModel))));
 q('#toy-signal').addEventListener('input',e=>{signal=Number(e.target.value);q('#toy-value').textContent=`${signal} / 100`;});
 q('#model-motion').addEventListener('click',()=>{modelPaused=!modelPaused;q('#model-motion').setAttribute('aria-pressed',modelPaused);q('#model-motion').textContent=modelPaused?'▶ Resume model animation':'Ⅱ Pause model animation';});
 qa('[data-explain-topic]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();document.getElementById(a.dataset.explainTopic).scrollIntoView({block:'start',behavior:reduceMotion.matches?'instant':'smooth'});}));
 function drawing(id){const canvas=q(id),ctx=canvas.getContext('2d');let width=0,height=0,mobile=false;new ResizeObserver(()=>{const r=canvas.getBoundingClientRect();width=r.width;height=r.height;mobile=width<600;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,width*dpr);canvas.height=Math.max(1,height*dpr);ctx.setTransform(dpr*width/1000,0,0,dpr*height/350,0,0);}).observe(canvas);return{ctx,get ready(){return width>0},get mobile(){return mobile}};}
 const wf=drawing('#workflow-canvas'),ml=drawing('#model-canvas');
 function clear(c){c.fillStyle='#161616';c.fillRect(0,0,1000,350);c.lineWidth=1;c.strokeStyle='#252525';for(let x=25;x<1000;x+=45){c.beginPath();c.moveTo(x,0);c.lineTo(x,350);c.stroke();}}
 function text(c,x,y,t,size=16,color='#ccc',align='center'){c.fillStyle=color;c.font=`${size}px sans-serif`;c.textAlign=align;c.fillText(t,x,y);}
 function box(c,x,y,w,h,label,active=false){c.fillStyle=active?'#deded7':'#252525';c.strokeStyle=active?'#fff':'#666';c.lineWidth=1;c.fillRect(x-w/2,y-h/2,w,h);c.strokeRect(x-w/2,y-h/2,w,h);text(c,x,y+5,label,16,active?'#111':'#ccc');}
 function line(c,a,b,t,active=true){c.strokeStyle=active?'#888':'#444';c.lineWidth=1;c.beginPath();c.moveTo(...a);c.lineTo(...b);c.stroke();if(active){const u=(t*.4)%1,x=a[0]+(b[0]-a[0])*u,y=a[1]+(b[1]-a[1])*u;c.fillStyle='#eee';c.fillRect(x-3,y-3,6,6);}}
 function workflow(){if(!wf.ready)return;const c=wf.ctx;clear(c);const t=time/1000,labels=['CONFIGURE','GENERATE','PHASES','OBSERVE','VALIDATE','EVALUATE'];text(c,35,30,`AN EXPERIMENT / STEP ${step+1} OF 6`,wf.mobile?21:13,'#888','left');
 if(step===0){
 // Dashed controller channels are distinct from solid packet-forwarding links.
 c.setLineDash([6,5]);line(c,[500,100],[270,175],t);line(c,[500,100],[730,175],t+.8);c.setLineDash([]);
 line(c,[370,205],[630,205],t);text(c,500,191,'DATA LINK',13,'#aaa');
 box(c,500,77,225,46,'RYU CONTROLLER',true);
 text(c,500,129,'OpenFlow 1.3 / control channels',14,'#aaa');
 for(const [x,id] of [[270,'S1'],[730,'S2']]){
 c.fillStyle='#303030';c.strokeStyle='#ddd';c.lineWidth=2;c.fillRect(x-105,175,210,76);c.strokeRect(x-105,175,210,76);
 text(c,x,197,'SWITCH '+id,18,'#fff');text(c,x,217,'Open vSwitch',14,'#ccc');
 for(let port=0;port<8;port++){const px=x-83+port*23;c.fillStyle='#111';c.fillRect(px,227,17,12);c.strokeStyle='#888';c.lineWidth=1;c.strokeRect(px,227,17,12);c.fillStyle=(Math.floor(t*3)+port)%4===0?'#eee':'#777';c.fillRect(px+5,242,7,3);}
 }
 for(const [i,x] of [150,390,610,850].entries()){line(c,[x<500?270:730,251],[x,279],t+i);box(c,x,298,135,38,'HOST H'+(i+1));}
 text(c,35,327,'ILLUSTRATIVE TOPOLOGY / VIRTUAL SWITCHES IN MININET',12,'#999','left');
 }
 if(step===1){const workload=Math.floor(t/2)%6;for(let i=0;i<6;i++){const x=95+i*162;box(c,x,110,140,45,['B00','B01','A01','A02','A03','A04'][i],i===workload);line(c,[x,133],[500,235],t+i,i===workload);}box(c,500,255,360,65,'CONTROLLED TRAFFIC',true);text(c,500,325,'WORKLOAD EXECUTION EVIDENCE ≠ ATTACK SUCCESS',wf.mobile?21:15,'#aaa');}
 if(step===2){const p=Math.floor(t/2.4)%3;for(let i=0;i<3;i++){const x=180+i*320;box(c,x,155,255,80,['STABLE','CONSTRAINED','RECOVERY'][i],i===p);text(c,x,230,['Reference settings','Applied constraints','Reference restored'][i],wf.mobile?24:18);}line(c,[180,275],[820,275],t);text(c,500,320,'VERIFY THE PHASE BOUNDARIES',wf.mobile?22:15,'#aaa');}
 if(step===3){['Flow counters','RTT samples','UDP logs','Event timestamps'].forEach((s,i)=>{box(c,200,75+i*65,240,40,s,i===Math.floor(t)%4);line(c,[320,75+i*65],[690,180],t+i);});box(c,800,180,260,90,'OBSERVATION');text(c,800,260,'features + run_id + time',wf.mobile?23:17,'#aaa');}
 if(step===4){['PHASE','ACTIVITY','QUALITY'].forEach((s,i)=>{box(c,210+i*290,110,240,60,s,i===Math.floor(t)%3);line(c,[210+i*290,140],[500,235],t+i);});box(c,500,260,480,60,'VALIDATED / TRACEABLE WINDOW',true);}
 if(step===5){box(c,180,170,220,70,'VALIDATED DATA',true);line(c,[290,170],[610,90],t);line(c,[290,170],[610,250],t+.7);box(c,770,90,300,70,'H23 / FROZEN MODELS');box(c,770,250,300,70,'H28 / NETWORK FIDELITY');text(c,500,325,'SEPARATE CAMPAIGNS / SEPARATE QUESTIONS',wf.mobile?21:15,'#aaa');}
 for(let i=0;i<6;i++){c.fillStyle=i===step?'#eee':'#555';c.fillRect(35+i*160,340,145,3);}
 }
 const sigmoid=x=>1/(1+Math.exp(-x));
 function prob(c,x,y,value,color='#8bb9cb'){c.fillStyle='#333';c.fillRect(x,y,250,18);c.fillStyle=color;c.fillRect(x,y,250*Math.max(0,Math.min(1,value)),18);text(c,x+280,y+15,(value*100).toFixed(0)+'%',20,'#ddd','left');}
 function models(){if(!ml.ready)return;const c=ml.ctx;clear(c);const t=modelTime/1000,s=signal/100;const toy=wf.mobile?20:13;text(c,35,30,'TOY INPUT / '+signal+' OF 100',toy,'#aaa','left');
 if(model===0){const score=(s-.5)*6,p=sigmoid(score);box(c,150,155,190,65,'FEATURE SIGNAL');line(c,[245,155],[380,155],t);box(c,500,155,240,65,'WEIGHTED SCORE',true);line(c,[620,155],[740,155],t+.8);box(c,850,155,220,65,'SIGMOID');text(c,500,225,'toy score: '+score.toFixed(2),22);prob(c,360,260,p);text(c,500,325,p>=.5?'TOY DECISION: CLASS 1':'TOY DECISION: CLASS 0',20,'#ddd');}
 if(model===1){const votes=[.35,.55,.7].map(v=>s>=v?.85:.15),avg=votes.reduce((a,b)=>a+b,0)/3;for(let i=0;i<3;i++){const x=175+i*320;box(c,x,90,180,42,'TOY TREE '+(i+1));const positive=votes[i]>.5;line(c,[x,111],[x-60,185],t, !positive);line(c,[x,111],[x+60,185],t,positive);box(c,x-60,195,90,35,'CLASS 0',!positive);box(c,x+60,195,90,35,'CLASS 1',positive);line(c,[x,215],[500,285],t+i);}text(c,500,320,'AVERAGE TOY PROBABILITY: '+(avg*100).toFixed(0)+'%',22,'#ddd');}
 if(model===2){const cx=500,cy=175,r=95;for(let i=0;i<38;i++){const angle=i*2.4,dist=i%2?55+(i%5)*5:140+(i%4)*12,x=cx+Math.cos(angle)*dist,y=cy+Math.sin(angle)*dist*.65;c.fillStyle=i%2?'#8db8cc':'#b39ada';c.beginPath();c.arc(x,y,4,0,Math.PI*2);c.fill();}c.strokeStyle='#ddd';c.setLineDash([5,6]);c.beginPath();c.ellipse(cx,cy,r,r*.75,0,0,Math.PI*2);c.stroke();c.setLineDash([]);const x=250+s*500;for(let k=0;k<3;k++){const ring=(t*25+k*20)%65;c.strokeStyle='#9996';c.beginPath();c.arc(x,cy,ring,0,Math.PI*2);c.stroke();}c.fillStyle='#fff';c.fillRect(x-6,cy-6,12,12);text(c,500,310,Math.abs(x-cx)<r?'TOY POINT: INSIDE NONLINEAR REGION':'TOY POINT: OUTSIDE NONLINEAR REGION',20);}
 if(model===3){const changes=[(s-.5)*2.2,(s-.35)*1.8,(s-.65)*1.4];let total=-.7;box(c,110,130,160,55,'BASE SCORE');for(let i=0;i<3;i++){total+=changes[i];const x=355+i*255;line(c,[i===0?190:x-175,130],[x-90,130],t+i);box(c,x,130,190,55,'CORRECTION '+(i+1),Math.floor(t)%3===i);text(c,x,205,(changes[i]>=0?'+':'')+changes[i].toFixed(2),28,'#ddd');}prob(c,365,265,sigmoid(total),'#a68bf0');text(c,500,325,'SEQUENTIAL IMPROVEMENT / ILLUSTRATIVE SCORES',18);}
 if(model===4){const vals=[sigmoid((s-.5)*6),[.35,.55,.7].map(v=>s>=v?.85:.15).reduce((a,b)=>a+b,0)/3,sigmoid((.38-Math.abs(s-.5))*7),sigmoid(-.7+(s-.5)*5.4)],avg=vals.reduce((a,b)=>a+b,0)/4;['LR','FOREST','RBF-SVM','BOOSTING'].forEach((name,i)=>{const y=75+i*65;box(c,180,y,190,40,name);prob(c,310,y-7,vals[i],['#4ea5ed','#51c7a4','#e6b254','#a68bf0'][i]);line(c,[630,y],[800,180],t+i);});box(c,850,180,220,70,(avg*100).toFixed(0)+'% / TOY VOTE',true);text(c,500,330,'EQUAL DEMO WEIGHTS ONLY / NOT STUDY PARAMETERS',17);}
 }
 function frame(now){const dt=last?Math.min(60,now-last):0;last=now;const visible=q('#explainer').classList.contains('route-active')&&!document.hidden;if(visible){if(!paused){time+=dt;if(!modelPaused)modelTime+=dt;if(walk){walkTime+=dt;if(walkTime>7200){if(step===5){stopWalk();q('#workflow-status').textContent='Walkthrough complete · Explore any stage again.';}else setStep(step+1);}}}workflow();models();}else if(walk)stopWalk();requestAnimationFrame(frame);}
 setStep(0);setModel(0);requestAnimationFrame(frame);
})();
